export type Tokens = typeof tokens

export type WindowClass = keyof typeof tokens.layout.window

/** The window class for a width in CSS pixels: the widest class whose minimum width fits. */
export function windowClass(width: number): WindowClass {
  const classes = Object.entries(tokens.layout.window) as [WindowClass, { minWidth: number }][]
  return classes.filter(([, w]) => width >= w.minWidth).sort((a, b) => b[1].minWidth - a[1].minWidth)[0][0]
}

export default tokens
